import { chromium } from 'playwright'

const BASE = 'http://127.0.0.1:8181'

const browser = await chromium.launch({ headless: true })
const ctx = await browser.newContext({ viewport: { width: 1920, height: 1080 } })

const reqs = []
ctx.on('request', (r) => {
  const u = r.url()
  if (u.includes('companyRecord')) reqs.push(u)
})

const page = await ctx.newPage()

// 注入 mock token 并登录态
try {
  await ctx.addInitScript(() => {
    const orig = sessionStorage.getItem.bind(sessionStorage)
    Object.defineProperty(sessionStorage, 'getItem', {
      configurable: true,
      value: (k) => (k === 'Admin-Token' ? 'mock' : orig(k))
    })
  })
} catch (e) {}

await page.goto(BASE + '/#/index', { waitUntil: 'domcontentloaded', timeout: 60000 }).catch(() => {})
await page.waitForTimeout(5000)

console.log('URL after load:', page.url())
console.log('companyRecord requests:', JSON.stringify(reqs, null, 2))

await browser.close()

